package com.spoonmeter;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.client.util.Filepath;

/**
 * The drop rates the rating is measured against, loaded from {@code drop_rates.json}.
 *
 * <p>A source is either simple - one counter, one set of rates - or split into <b>variants</b>. One
 * collection log page can cover several activities with different rates and their own counters: the
 * Gauntlet page counts normal and corrupted runs separately at 1/120 and 1/50, the raid pages count
 * normal, entry and hard/expert completions, and the Dagannoth Kings page counts all three kings.
 * Each variant names the counter it applies to, and expectations are summed across them.
 *
 * <p>Lookups are done on normalised names so that "Kree'arra", "kreearra" and the collection log's
 * own spelling all land on the same entry, and so that item names survive the log's
 * "(uncharged)" style suffixes.
 */
public class DropTable
{
	public static final String RESOURCE = "/com/spoonmeter/drop_rates.json";

	public static class Definition
	{
		int version;
		String note;
		List<Source> sources;
	}

	public static class Source
	{
		String name;
		List<String> aliases;
		boolean approx;

		// Simple form: one implicit variant.
		String counter;
		String uniqueChanceKey;
		Double totalWeight;
		List<Item> items;

		// Split form.
		List<Variant> variants;

		private transient List<Variant> effective;

		public String getName()
		{
			return name;
		}

		public boolean isApprox()
		{
			return approx;
		}

		/** The split variants, or a single synthesised one for a simple source. */
		public List<Variant> getVariants()
		{
			if (effective == null)
			{
				if (variants != null && !variants.isEmpty())
				{
					effective = variants;
				}
				else
				{
					Variant single = new Variant();
					single.counter = counter;
					single.uniqueChanceKey = uniqueChanceKey;
					single.totalWeight = totalWeight;
					single.items = items;
					effective = Collections.singletonList(single);
				}
			}

			return effective;
		}

		/** Every distinct item across all variants, in table order. */
		public List<Item> getItems()
		{
			Set<String> seen = new LinkedHashSet<>();
			List<Item> out = new ArrayList<>();

			for (Variant variant : getVariants())
			{
				for (Item item : variant.getItems())
				{
					if (seen.add(normalise(item.name)))
					{
						out.add(item);
					}
				}
			}

			return out;
		}
	}

	public static class Variant
	{
		String counter;
		String uniqueChanceKey;
		Double totalWeight;
		List<Item> items;

		/** Name of the page counter this variant is rolled by, or null to use the page's largest. */
		@Nullable
		public String getCounter()
		{
			return counter;
		}

		@Nullable
		public String getUniqueChanceKey()
		{
			return uniqueChanceKey;
		}

		public List<Item> getItems()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	public static class Item
	{
		String name;
		Double rate;
		Double weight;
		Double chance;

		public String getName()
		{
			return name;
		}
	}

	private final List<Source> sources;
	private final Map<String, Source> byNormalisedName = new HashMap<>();

	private DropTable(List<Source> sources)
	{
		this.sources = sources;

		for (Source source : sources)
		{
			byNormalisedName.put(normalise(source.name), source);

			if (source.aliases != null)
			{
				for (String alias : source.aliases)
				{
					byNormalisedName.put(normalise(alias), source);
				}
			}
		}
	}

	/**
	 * Loads the bundled table, or the user's own copy if {@code override} exists. Letting people
	 * drop a corrected file next to their RuneLite settings means a wrong rate never needs a
	 * plugin update to fix.
	 */
	public static DropTable load(Gson gson, @Nullable Filepath override) throws IOException
	{
		if (override != null && override.isFile())
		{
			try (Reader reader = override.openBufferedReader())
			{
				return fromReader(gson, reader);
			}
		}

		try (InputStream in = DropTable.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing bundled drop table: " + RESOURCE);
			}

			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return fromReader(gson, reader);
			}
		}
	}

	private static DropTable fromReader(Gson gson, Reader reader) throws IOException
	{
		Definition definition = gson.fromJson(reader, Definition.class);

		if (definition == null || definition.sources == null || definition.sources.isEmpty())
		{
			throw new IOException("Drop table is empty or malformed");
		}

		return new DropTable(new ArrayList<>(definition.sources));
	}

	public List<Source> getSources()
	{
		return Collections.unmodifiableList(sources);
	}

	@Nullable
	public Source find(String collectionLogPageName)
	{
		if (collectionLogPageName == null)
		{
			return null;
		}

		return byNormalisedName.get(normalise(collectionLogPageName));
	}

	/**
	 * Per-completion chance of a single item within one variant.
	 *
	 * @param uniqueChance chance of any unique per completion, used by the weight-based raid
	 *                     entries; ignored by entries that state a flat rate.
	 */
	public static double probability(Variant variant, Item item, double uniqueChance)
	{
		if (item.chance != null && item.chance > 0)
		{
			return item.chance;
		}

		if (item.rate != null && item.rate > 0)
		{
			return 1.0 / item.rate;
		}

		if (item.weight != null && variant.totalWeight != null && variant.totalWeight > 0)
		{
			return uniqueChance * (item.weight / variant.totalWeight);
		}

		return 0.0;
	}

	/** Item name to per-completion chance for one variant, in table order. */
	public static Map<String, Double> probabilities(Variant variant, double uniqueChance)
	{
		Map<String, Double> out = new LinkedHashMap<>();

		for (Item item : variant.getItems())
		{
			double p = probability(variant, item, uniqueChance);

			if (p > 0)
			{
				out.put(item.name, p);
			}
		}

		return out;
	}

	/**
	 * Lowercase, drop bracketed qualifiers such as "(uncharged)", and strip punctuation, so that
	 * apostrophes and the game's occasional renames do not break a lookup.
	 */
	public static String normalise(String name)
	{
		if (name == null)
		{
			return "";
		}

		String s = name.toLowerCase(Locale.ENGLISH);
		s = s.replaceAll("\\(.*?\\)", " ");
		s = s.replaceAll("[^a-z0-9 ]", "");
		s = s.replaceAll("\\s+", " ").trim();

		if (s.startsWith("the "))
		{
			s = s.substring(4);
		}

		return s;
	}

	/**
	 * Counter labels get a gentler normalisation than item names: the bracketed part is the whole
	 * distinction between "Chambers of Xeric completions" and "Chambers of Xeric (CM) completions",
	 * so brackets are unwrapped rather than dropped.
	 */
	public static String normaliseCounter(String label)
	{
		if (label == null)
		{
			return "";
		}

		String s = label.toLowerCase(Locale.ENGLISH);
		s = s.replaceAll("[^a-z0-9 ]", " ");
		return s.replaceAll("\\s+", " ").trim();
	}
}

package com.spoonmeter;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Spoon Meter",
	description = "Rates how spooned or cursed your account is from collection log KC and uniques",
	tags = {"collection", "log", "luck", "drop", "rate", "spoon", "dry", "rng"},
	internalName = "spoon-meter"
)
public class SpoonMeterPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SpoonMeterPlugin.class);

	private static final String COMMAND = "spoon";
	private static final String PUBLIC_COMMAND = "!spoon";
	private static final int SAVE_INTERVAL_TICKS = 50; // ~30 seconds

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ChatCommandManager chatCommandManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private SpoonMeterConfig config;

	private final Map<String, CollectionLogPage> pages = new LinkedHashMap<>();

	private CollectionLogParser parser;
	private DropTable dropTable;
	private SpoonMeterPanel panel;
	private NavigationButton navButton;

	private boolean dirty;
	private boolean commandRegistered;
	private int ticksSinceSave;
	private Filepath dataDir;
	private String loadedProfileKey;
	private String lastFingerprint;

	@Provides
	SpoonMeterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpoonMeterConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		parser = new CollectionLogParser(itemManager);

		dataDir = getPluginDirectory();
		dataDir.createDirectories();
		dropTable = DropTable.load(gson, dataDir.joinSegment("drop_rates.json"));

		panel = new SpoonMeterPanel(this);

		BufferedImage icon = ImageUtil.loadImageResource(SpoonMeterPlugin.class, "/com/spoonmeter/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Spoon Meter")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		setChatCommandRegistered(config.publicChatCommand());

		loadForCurrentProfile();
		refreshPanel();

		log.info("Spoon Meter started: sidebar button added, {} drop sources, {} saved pages",
			dropTable.getSources().size(), pages.size());
	}

	@Override
	protected void shutDown() throws Exception
	{
		flush(false);
		setChatCommandRegistered(false);
		clientToolbar.removeNavigation(navButton);
		pages.clear();
		panel = null;
		navButton = null;
		lastFingerprint = null;
		loadedProfileKey = null;
		dataDir = null;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadForCurrentProfile();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadForCurrentProfile();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			flush();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == CollectionLogParser.COLLECTION_LOG_GROUP_ID)
		{
			lastFingerprint = null;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == CollectionLogParser.COLLECTION_LOG_GROUP_ID)
		{
			lastFingerprint = null;
			flush();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Checked every tick rather than tracked with a flag: enabling the plugin while the log is
		// already open still works, and a missed close event cannot wedge it.
		if (parser.isLogOpen(client))
		{
			readOpenPage();
		}

		if (dirty && ++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			flush();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SpoonMeterConfig.GROUP.equals(event.getGroup()))
		{
			setChatCommandRegistered(config.publicChatCommand());
			refreshPanel();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!config.chatCommand() || !COMMAND.equalsIgnoreCase(event.getCommand()))
		{
			return;
		}

		SpoonReport report = buildReport();

		String message = report.isEmpty()
			? new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Spoon Meter: ")
				.append(ChatColorType.NORMAL).append("no rated pages yet - open your collection log.")
				.build()
			: new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Spoon Meter: ")
				.append(ChatColorType.NORMAL).append(SpoonSummary.oneLine(report))
				.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/**
	 * Handles {@code !spoon} typed into public, clan or friends chat.
	 *
	 * <p>This rewrites the message where it is displayed, exactly like {@code !kc} does. Everyone
	 * else still receives the literal "!spoon" text: the client cannot alter what is sent, and
	 * nobody else's client holds this account's collection log to look the answer up with.
	 */
	private void onSpoonChatCommand(ChatMessage chatMessage, String message)
	{
		Player local = client.getLocalPlayer();

		// Someone else's !spoon must be left alone rather than answered with our numbers.
		if (local == null || local.getName() == null
			|| !local.getName().equals(Text.sanitize(chatMessage.getName())))
		{
			return;
		}

		SpoonReport report = buildReport();
		String argument = message.length() > PUBLIC_COMMAND.length()
			? message.substring(PUBLIC_COMMAND.length()) : "";

		String line = report.isEmpty()
			? "Spoon Meter: no rated pages yet"
			: SpoonSummary.chatLine(report, argument);

		MessageNode node = chatMessage.getMessageNode();
		node.setRuneLiteFormatMessage(new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(line)
			.build());

		client.refreshChat();
	}

	private void setChatCommandRegistered(boolean wanted)
	{
		if (wanted == commandRegistered)
		{
			return;
		}

		if (wanted)
		{
			chatCommandManager.registerCommand(PUBLIC_COMMAND, this::onSpoonChatCommand);
		}
		else
		{
			chatCommandManager.unregisterCommand(PUBLIC_COMMAND);
		}

		commandRegistered = wanted;
	}

	/** Called by the panel when the user picks a different sort order. */
	void setSortMode(SortMode sortMode)
	{
		if (sortMode != null && sortMode != config.sortMode())
		{
			configManager.setConfiguration(SpoonMeterConfig.GROUP, "sortMode", sortMode);
		}
	}

	private void readOpenPage()
	{
		CollectionLogPage page = parser.parseOpenPage(client);

		if (page == null)
		{
			return;
		}

		String fingerprint = page.fingerprint();

		if (fingerprint.equals(lastFingerprint))
		{
			return;
		}

		lastFingerprint = fingerprint;

		CollectionLogPage previous = pages.put(page.getName(), page);

		if (previous == null || !previous.fingerprint().equals(fingerprint))
		{
			dirty = true;
			refreshPanel();
		}
	}

	private SpoonReport buildReport()
	{
		Map<String, Double> uniqueChances = new HashMap<>();
		uniqueChances.put("cox", config.coxUniqueChance() / 100.0);
		uniqueChances.put("coxcm", config.coxCmUniqueChance() / 100.0);
		uniqueChances.put("tob", config.tobUniqueChance() / 100.0);
		uniqueChances.put("tobhm", config.tobHardUniqueChance() / 100.0);
		uniqueChances.put("toa", config.toaUniqueChance() / 100.0);
		uniqueChances.put("toaexpert", config.toaExpertUniqueChance() / 100.0);

		return SpoonReport.build(pages.values(), dropTable, uniqueChances, config.minimumKc());
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		SpoonReport report = buildReport();
		SortMode sortMode = config.sortMode();
		SwingUtilities.invokeLater(() -> panel.update(report, sortMode));
	}

	// --- persistence ----------------------------------------------------------------------
	// Kept as a file rather than in the config service: a full collection log is far too big to be
	// sensible as a synced config value, and it is per account anyway. All of it goes through
	// Filepath, which confines the plugin to its own directory under ~/.runelite/plugin-data.

	private Filepath dataFile(String profileKey)
	{
		// Filepath rejects anything that could escape the directory, but a profile key is not meant to
		// carry punctuation in the first place, so it is flattened before it gets there.
		return dataDir.joinSegment(profileKey.replaceAll("[^A-Za-z0-9_.-]", "_") + ".json");
	}

	/**
	 * RuneLite's RS profile key identifies the logged in account without exposing anything about it,
	 * and changes when you switch accounts, which is exactly when the saved log should switch too.
	 */
	private void loadForCurrentProfile()
	{
		String profileKey = configManager.getRSProfileKey();

		if (profileKey == null || profileKey.equals(loadedProfileKey) || dataDir == null)
		{
			return;
		}

		flush();

		loadedProfileKey = profileKey;
		pages.clear();
		lastFingerprint = null;

		Filepath file = dataFile(profileKey);

		if (file.isFile())
		{
			Type type = new TypeToken<Map<String, CollectionLogPage>>()
			{
			}.getType();

			try (Reader reader = file.openBufferedReader())
			{
				Map<String, CollectionLogPage> saved = gson.fromJson(reader, type);

				if (saved != null)
				{
					pages.putAll(saved);
					dropStalePersonalBests();
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Could not read saved collection log data from {}", file, e);
			}
		}

		refreshPanel();
	}

	/**
	 * Earlier builds read "Personal Best: 9:51" as a counter called "Personal Best: 9" worth 51,
	 * which outranks the real kill count on any page with fewer kills than that. The parser no
	 * longer produces them, but saved files still hold them until each page is opened again.
	 */
	private void dropStalePersonalBests()
	{
		int removed = 0;

		for (CollectionLogPage page : pages.values())
		{
			removed += page.getCounters().keySet()
				.removeIf(label -> label.toLowerCase(Locale.ENGLISH).startsWith("personal best")) ? 1 : 0;
		}

		if (removed > 0)
		{
			dirty = true;
			log.info("Dropped personal best times from {} saved pages", removed);
		}
	}

	/** Writes pending changes off the client thread. */
	private void flush()
	{
		flush(true);
	}

	private void flush(boolean async)
	{
		ticksSinceSave = 0;

		if (!dirty || loadedProfileKey == null || dataDir == null || pages.isEmpty())
		{
			return;
		}

		dirty = false;

		Map<String, CollectionLogPage> snapshot = new LinkedHashMap<>(pages);
		Filepath file = dataFile(loadedProfileKey);

		if (async)
		{
			executor.execute(() -> write(file, snapshot));
		}
		else
		{
			// On shutdown there may be no executor left to run it later.
			write(file, snapshot);
		}
	}

	private void write(Filepath file, Map<String, CollectionLogPage> snapshot)
	{
		try (Writer writer = file.openBufferedWriter())
		{
			gson.toJson(snapshot, writer);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not save collection log data to {}", file, e);
		}
	}
}

package com.spoonmeter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

/**
 * One boss/raid in the list. Click it to see which item is doing the bullying.
 *
 * <p>Every row puts its long text in {@code BorderLayout.CENTER} and its short value in
 * {@code EAST}. The sidebar is a fixed 225px, and a long name in {@code WEST} keeps its full
 * preferred width and overlaps the value; in {@code CENTER} it gets whatever is left over and
 * ellipsises. The full text is always on the tooltip.
 */
class SourceRow extends JPanel
{
	private static final Color DRY_TEXT = new Color(0xE0A030);
	private static final Color VERY_DRY_TEXT = new Color(0xE05A45);

	private final JPanel details;
	private boolean expanded;

	SourceRow(SpoonReport.SourceLine line)
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(6, 8, 6, 8));

		JPanel summary = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		summary.setOpaque(false);

		JPanel titleRow = new JPanel(new BorderLayout(4, 0));
		titleRow.setOpaque(false);

		JLabel name = new JLabel(line.getName() + (line.isApproximate() ? " *" : ""));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);

		JLabel verdict = new JLabel(line.getRating().getTitle());
		verdict.setFont(FontManager.getRunescapeSmallFont());
		verdict.setForeground(line.getRating().getColor());

		titleRow.add(name, BorderLayout.CENTER);
		titleRow.add(verdict, BorderLayout.EAST);

		LuckBar bar = new LuckBar(6);
		bar.setPercentile(line.getPercentile());

		JPanel statsRow = new JPanel(new BorderLayout(4, 0));
		statsRow.setOpaque(false);

		// Just "1,498 kc" - the real counter names ("Corrupted Gauntlet completion count") are far
		// too long for the sidebar, so they live on the tooltip instead.
		JLabel kc = new JLabel(SpoonSummary.WHOLE.format(line.getKc()) + " kc");
		kc.setFont(FontManager.getRunescapeSmallFont());
		kc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JLabel ratio = new JLabel(line.getObtained() + " / " + SpoonSummary.ONE_DP.format(line.getExpected())
			+ "  (" + SpoonSummary.ONE_DP.format(line.getRatio()) + "x)");
		ratio.setFont(FontManager.getRunescapeSmallFont());
		ratio.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		statsRow.add(kc, BorderLayout.WEST);
		statsRow.add(ratio, BorderLayout.EAST);

		summary.add(titleRow);
		summary.add(bar);
		summary.add(statsRow);

		details = buildDetails(line);
		details.setVisible(false);

		add(summary, BorderLayout.NORTH);
		add(details, BorderLayout.CENTER);

		setToolTipText(buildTooltip(line));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				expanded = !expanded;
				details.setVisible(expanded);
				revalidate();
				repaint();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
	}

	private static String buildTooltip(SpoonReport.SourceLine line)
	{
		StringBuilder tip = new StringBuilder("<html>").append(line.getName());

		for (Map.Entry<String, Integer> counter : line.getCounters().entrySet())
		{
			tip.append("<br>").append(counter.getKey()).append(": ")
				.append(SpoonSummary.WHOLE.format(counter.getValue()));
		}

		tip.append("<br>").append(line.getObtained()).append(" uniques vs ")
			.append(SpoonSummary.ONE_DP.format(line.getExpected())).append(" expected")
			.append("<br>Luckier than ").append(LuckRating.spoonScore(line.getPercentile()))
			.append("% of accounts");

		if (line.isApproximate())
		{
			tip.append("<br>* rates vary with team size / points");
		}

		return tip.append("<br>Click for the item breakdown</html>").toString();
	}

	private JPanel buildDetails(SpoonReport.SourceLine line)
	{
		JPanel panel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		panel.setOpaque(false);
		panel.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(6, 0, 0, 0),
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR)));

		for (SpoonReport.ItemLine item : line.getItems())
		{
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setOpaque(false);
			row.setBorder(new EmptyBorder(3, 0, 0, 0));

			JLabel name = new JLabel(item.getName());
			name.setFont(FontManager.getRunescapeSmallFont());

			String right;
			Color colour;

			if (item.getObtained() > 0)
			{
				name.setForeground(Color.WHITE);
				right = item.getObtained() + " / " + SpoonSummary.ONE_DP.format(item.getExpected());
				colour = ColorScheme.LIGHT_GRAY_COLOR;
			}
			else
			{
				name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				long percent = Math.round(item.getDryness() * 100);
				right = percent + "% have it";
				colour = item.getDryness() >= 0.95 ? VERY_DRY_TEXT
					: item.getDryness() >= 0.75 ? DRY_TEXT : ColorScheme.LIGHT_GRAY_COLOR;
			}

			JLabel value = new JLabel(right);
			value.setFont(FontManager.getRunescapeSmallFont());
			value.setForeground(colour);

			row.setToolTipText("<html>" + item.getName()
				+ "<br>1 in " + SpoonSummary.WHOLE.format(Math.round(1.0 / item.getChance())) + " per attempt"
				+ "<br>" + SpoonSummary.ONE_DP.format(item.getExpected()) + " expected, "
				+ item.getObtained() + " obtained</html>");

			row.add(name, BorderLayout.CENTER);
			row.add(value, BorderLayout.EAST);
			panel.add(row);
		}

		return panel;
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.spoonmeter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * A cursed-to-spooned strip with a marker at the account's percentile. Reading a percentile off a
 * bar is a lot faster than reading it off a number, and the colour does the editorialising.
 */
class LuckBar extends JComponent
{
	private static final Color CURSED = new Color(0xC62828);
	private static final Color MIDDLE = new Color(0x9E9E9E);
	private static final Color SPOONED = new Color(0xFFC107);

	private double percentile;

	LuckBar(int height)
	{
		setPreferredSize(new Dimension(0, height));
		setMinimumSize(new Dimension(0, height));
	}

	void setPercentile(double percentile)
	{
		this.percentile = Math.max(0, Math.min(1, percentile));
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();

		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			int w = getWidth();
			int h = getHeight();
			int arc = Math.min(h, 8);

			g2.setColor(ColorScheme.DARK_GRAY_COLOR);
			g2.fillRoundRect(0, 0, w, h, arc, arc);

			g2.setPaint(new GradientPaint(0, 0, CURSED, w / 2f, 0, MIDDLE));
			g2.fillRoundRect(0, 0, w / 2, h, arc, arc);

			g2.setPaint(new GradientPaint(w / 2f, 0, MIDDLE, w, 0, SPOONED));
			g2.fillRoundRect(w / 2, 0, w - w / 2, h, arc, arc);

			int x = (int) Math.round(percentile * (w - 3));
			g2.setColor(Color.WHITE);
			g2.fillRect(x, -1, 3, h + 2);
			g2.setColor(new Color(0, 0, 0, 120));
			g2.drawRect(x, -1, 3, h + 2);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.spoonmeter;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Reads whichever collection log page is currently on screen.
 *
 * <p>Deliberately structural rather than hardcoded to child indices: it walks the interface looking
 * for the "Obtained: x/y" line to identify the header, and for the widget holding the most item
 * children to identify the item grid. Jagex reshuffles these child ids from time to time, and this
 * survives that.
 */
class CollectionLogParser
{
	static final int COLLECTION_LOG_GROUP_ID = 621;

	private static final int MAX_ROOT_CHILDREN = 100;
	private static final int MAX_DEPTH = 8;

	private static final Pattern OBTAINED = Pattern.compile("^Obtained:\\s*(\\d+)\\s*/\\s*(\\d+)$");

	// The label deliberately cannot contain a colon. Pages also show personal best times such as
	// "Personal Best: 9:51", and a looser pattern reads those as a counter named "Personal Best: 9"
	// with a value of 51 - which then beats the real kill count on any page with a low KC.
	private static final Pattern COUNTER = Pattern.compile("^([^:]+):\\s*([\\d,]+)$");

	private final ItemManager itemManager;

	CollectionLogParser(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	boolean isLogOpen(Client client)
	{
		for (int childId = 0; childId < MAX_ROOT_CHILDREN; childId++)
		{
			if (client.getWidget(COLLECTION_LOG_GROUP_ID, childId) != null)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * @return the page currently displayed, or null if the log is closed or no page is selected.
	 */
	@Nullable
	CollectionLogPage parseOpenPage(Client client)
	{
		Scan scan = new Scan();

		for (int childId = 0; childId < MAX_ROOT_CHILDREN; childId++)
		{
			Widget root = client.getWidget(COLLECTION_LOG_GROUP_ID, childId);

			if (root != null)
			{
				walk(root, 0, scan);
			}
		}

		if (scan.header == null || scan.itemContainer == null)
		{
			return null;
		}

		CollectionLogPage page = readHeader(scan.header);

		if (page == null)
		{
			return null;
		}

		page.setItems(readItems(scan.itemContainer));
		page.setUpdatedMillis(System.currentTimeMillis());
		return page;
	}

	private void walk(Widget widget, int depth, Scan scan)
	{
		if (widget == null || depth > MAX_DEPTH)
		{
			return;
		}

		List<Widget> children = childrenOf(widget);

		if (!children.isEmpty())
		{
			int itemCount = 0;

			for (Widget child : children)
			{
				if (child.getItemId() > 0)
				{
					itemCount++;
				}

				String text = Text.removeTags(nullToEmpty(child.getText()));

				if (OBTAINED.matcher(text).matches())
				{
					scan.header = widget;
				}
			}

			// The item grid is the one widget on the page holding a wall of items; the tab list and
			// header hold at most a handful, so "most items wins" is a safe way to pick it out.
			if (itemCount > scan.itemCount)
			{
				scan.itemCount = itemCount;
				scan.itemContainer = widget;
			}
		}

		for (Widget child : children)
		{
			walk(child, depth + 1, scan);
		}
	}

	@Nullable
	private CollectionLogPage readHeader(Widget header)
	{
		List<Widget> children = childrenOf(header);

		String title = null;
		int obtainedIndex = -1;
		int obtained = 0;
		int total = 0;
		Map<String, Integer> counters = new LinkedHashMap<>();

		for (int i = 0; i < children.size(); i++)
		{
			String text = Text.removeTags(nullToEmpty(children.get(i).getText())).trim();

			if (text.isEmpty())
			{
				continue;
			}

			Matcher obtainedMatcher = OBTAINED.matcher(text);

			if (obtainedMatcher.matches())
			{
				obtainedIndex = i;
				obtained = parseInt(obtainedMatcher.group(1));
				total = parseInt(obtainedMatcher.group(2));
				continue;
			}

			if (obtainedIndex < 0)
			{
				// Anything before the "Obtained" line is the page title.
				if (title == null)
				{
					title = text;
				}

				continue;
			}

			addCounter(counters, text);
		}

		if (title == null || obtainedIndex < 0)
		{
			return null;
		}

		CollectionLogPage page = new CollectionLogPage(title);
		page.setObtained(obtained);
		page.setTotal(total);
		page.setCounters(counters);
		return page;
	}

	/**
	 * Records a "Label: 1,234" header line as a counter.
	 *
	 * @return false if the line is not a counter at all, such as a "Personal Best: 9:51" time
	 */
	static boolean addCounter(Map<String, Integer> counters, String text)
	{
		Matcher matcher = COUNTER.matcher(text);

		if (!matcher.matches())
		{
			return false;
		}

		counters.put(matcher.group(1).trim(), parseInt(matcher.group(2)));
		return true;
	}

	private Map<String, Integer> readItems(Widget container)
	{
		Map<String, Integer> items = new LinkedHashMap<>();

		for (Widget child : childrenOf(container))
		{
			int itemId = child.getItemId();

			if (itemId <= 0)
			{
				continue;
			}

			// Unobtained entries are drawn faded; obtained ones are fully opaque.
			if (child.getOpacity() != 0)
			{
				continue;
			}

			String name = Text.removeTags(nullToEmpty(child.getName())).trim();

			if (name.isEmpty() && itemManager != null)
			{
				name = itemManager.getItemComposition(itemId).getName();
			}

			if (name.isEmpty())
			{
				continue;
			}

			int quantity = Math.max(1, child.getItemQuantity());
			items.merge(name, quantity, Integer::sum);
		}

		return items;
	}

	private static List<Widget> childrenOf(Widget widget)
	{
		List<Widget> out = new ArrayList<>();
		addAll(out, widget.getStaticChildren());
		addAll(out, widget.getDynamicChildren());
		addAll(out, widget.getNestedChildren());
		return out;
	}

	private static void addAll(List<Widget> out, @Nullable Widget[] widgets)
	{
		if (widgets == null)
		{
			return;
		}

		for (Widget widget : widgets)
		{
			if (widget != null)
			{
				out.add(widget);
			}
		}
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw.replace(",", "").trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String nullToEmpty(@Nullable String s)
	{
		return s == null ? "" : s;
	}

	private static final class Scan
	{
		private Widget header;
		private Widget itemContainer;
		private int itemCount;
	}
}

package com.spoonmeter;

import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.List;

/** Turns a report into text, for the clipboard button and the chat command. */
final class SpoonSummary
{
	static final DecimalFormat ONE_DP = new DecimalFormat("#,##0.0");
	static final DecimalFormat WHOLE = new DecimalFormat("#,##0");

	private SpoonSummary()
	{
	}

	/** "Cursed - 12/100 - 14 uniques vs 21.3 expected (0.66x)". */
	static String oneLine(SpoonReport report)
	{
		return report.getRating().getTitle()
			+ " - " + report.getSpoonScore() + "/100 - "
			+ WHOLE.format(report.getObtained()) + " uniques vs "
			+ ONE_DP.format(report.getExpected()) + " expected ("
			+ ONE_DP.format(report.getRatio()) + "x)";
	}

	/** The game's public/clan chat box refuses anything longer than this. */
	static final int MAX_CHAT_LENGTH = 80;

	/**
	 * A single line that fits in a game chat message. Detail is dropped in order of importance until
	 * it fits, so a long rating name plus large numbers degrades gracefully instead of being cut off
	 * mid-word.
	 *
	 * @param argument optional boss name; blank for the account-wide verdict
	 */
	static String chatLine(SpoonReport report, String argument)
	{
		String subject = "";
		LuckRating rating = report.getRating();
		int score = report.getSpoonScore();
		int obtained = report.getObtained();
		double expected = report.getExpected();
		double ratio = report.getRatio();

		// Only a single page has a kill count worth printing. Summing attempts across different
		// bosses would be a number that means nothing, so the account line goes without.
		int kc = 0;

		if (argument != null && !argument.trim().isEmpty())
		{
			SpoonReport.SourceLine match = findSource(report, argument);

			if (match == null)
			{
				return "Spoon Meter: no rated page matching " + argument.trim();
			}

			subject = " " + match.getName();
			rating = match.getRating();
			score = LuckRating.spoonScore(match.getPercentile());
			obtained = match.getObtained();
			expected = match.getExpected();
			ratio = match.getRatio();
			kc = match.getKc();
		}

		String head = "Spoon Meter" + subject + ": " + rating.getTitle() + " (" + score + "/100)";
		String lead = kc > 0 ? " - " + WHOLE.format(kc) + " kc," : " -";

		String[] candidates = {
			head + lead + " " + WHOLE.format(obtained) + " uniques vs " + ONE_DP.format(expected)
				+ " expected, " + ONE_DP.format(ratio) + "x",
			head + lead + " " + WHOLE.format(obtained) + " vs " + ONE_DP.format(expected)
				+ ", " + ONE_DP.format(ratio) + "x",
			head + lead + " " + ONE_DP.format(ratio) + "x",
			head + (kc > 0 ? " - " + WHOLE.format(kc) + " kc" : ""),
			head
		};

		for (String candidate : candidates)
		{
			if (candidate.length() <= MAX_CHAT_LENGTH)
			{
				return candidate;
			}
		}

		String shortest = candidates[candidates.length - 1];
		return shortest.length() <= MAX_CHAT_LENGTH ? shortest : shortest.substring(0, MAX_CHAT_LENGTH);
	}

	private static SpoonReport.SourceLine findSource(SpoonReport report, String argument)
	{
		String wanted = DropTable.normalise(argument);

		for (SpoonReport.SourceLine source : report.getSources())
		{
			if (DropTable.normalise(source.getName()).equals(wanted))
			{
				return source;
			}
		}

		for (SpoonReport.SourceLine source : report.getSources())
		{
			if (DropTable.normalise(source.getName()).contains(wanted))
			{
				return source;
			}
		}

		return null;
	}

	static String forClipboard(SpoonReport report, SortMode sortMode)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("Spoon Meter\n");
		sb.append(oneLine(report)).append('\n');
		sb.append("Luckier than ").append(report.getSpoonScore())
			.append("% of accounts at the same KC.\n\n");

		List<SpoonReport.SourceLine> sources = new ArrayList<>(report.getSources());
		sources.sort(sortMode.getComparator());

		for (SpoonReport.SourceLine source : sources)
		{
			sb.append(source.getName())
				.append(" - ").append(WHOLE.format(source.getKc())).append(" kc - ")
				.append(source.getObtained()).append('/').append(ONE_DP.format(source.getExpected()))
				.append(" (").append(ONE_DP.format(source.getRatio())).append("x) - ")
				.append(source.getRating().getTitle());

			SpoonReport.ItemLine driest = source.getDriestMissing();

			if (driest != null)
			{
				sb.append(" - driest: ").append(driest.getName())
					.append(" (").append(Math.round(driest.getDryness() * 100)).append("% have it)");
			}

			sb.append('\n');
		}

		return sb.toString();
	}
}

package com.spoonmeter;

import java.awt.Color;

/**
 * The verdict bands. Each covers a slice of the luck percentile, from "the drop table loves you"
 * down to "the drop table has personally wronged you".
 */
public enum LuckRating
{
	SPOONED_BY_THE_GODS(0.99, "Spooned by the Gods", new Color(0xFFD700), "Top 1%. Please stop."),
	ABSOLUTELY_SPOONED(0.95, "Absolutely Spooned", new Color(0xFFB300), "You have been handed things."),
	SPOONED(0.85, "Spooned", new Color(0x8BE28B), "Comfortably ahead of rate."),
	BLESSED(0.65, "Blessed", new Color(0x5DBB63), "A quietly lucky account."),
	AVERAGE(0.35, "Painfully Average", new Color(0xC8C8C8), "Exactly what the wiki promised."),
	A_BIT_DRY(0.15, "A Bit Dry", new Color(0xE0A030), "Behind rate, but survivable."),
	CURSED(0.05, "Cursed", new Color(0xFF7043), "The drop table is ignoring you."),
	HARD_CURSED(0.01, "Hard Cursed", new Color(0xE53935), "Bottom 5%. Genuinely unlucky."),
	RNG_HATES_YOU(0.0, "RNG Hates You", new Color(0xC2185B), "Bottom 1%. Consider a new hobby.");

	private final double minPercentile;
	private final String title;
	private final Color color;
	private final String blurb;

	LuckRating(double minPercentile, String title, Color color, String blurb)
	{
		this.minPercentile = minPercentile;
		this.title = title;
		this.color = color;
		this.blurb = blurb;
	}

	public String getTitle()
	{
		return title;
	}

	public Color getColor()
	{
		return color;
	}

	public String getBlurb()
	{
		return blurb;
	}

	public double getMinPercentile()
	{
		return minPercentile;
	}

	public static LuckRating fromPercentile(double percentile)
	{
		for (LuckRating rating : values())
		{
			if (percentile >= rating.minPercentile)
			{
				return rating;
			}
		}

		return RNG_HATES_YOU;
	}

	/** 0-100 "spoon score", which is just the percentile in a friendlier costume. */
	public static int spoonScore(double percentile)
	{
		return (int) Math.round(percentile * 100.0);
	}
}

package com.spoonmeter;

import java.util.Comparator;

public enum SortMode
{
	CURSED_FIRST("Cursed first", Comparator.comparingDouble(SpoonReport.SourceLine::getPercentile)),
	SPOONED_FIRST("Spooned first", Comparator.comparingDouble(SpoonReport.SourceLine::getPercentile).reversed()),
	KC("Highest KC", Comparator.comparingInt(SpoonReport.SourceLine::getKc).reversed()),
	NAME("Name", Comparator.comparing(SpoonReport.SourceLine::getName, String.CASE_INSENSITIVE_ORDER));

	private final String label;
	private final Comparator<SpoonReport.SourceLine> comparator;

	SortMode(String label, Comparator<SpoonReport.SourceLine> comparator)
	{
		this.label = label;
		this.comparator = comparator;
	}

	public Comparator<SpoonReport.SourceLine> getComparator()
	{
		return comparator;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.spoonmeter;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One page of the collection log as it was last seen: its counters and the uniques already
 * obtained. Only obtained items are stored; anything missing is worked out from the drop table,
 * which keeps the saved file small and stops it going stale when Jagex adds items to a page.
 */
public class CollectionLogPage
{
	private String name;
	private int obtained;
	private int total;
	private Map<String, Integer> counters = new LinkedHashMap<>();
	private Map<String, Integer> items = new LinkedHashMap<>();
	private long updatedMillis;

	public CollectionLogPage()
	{
	}

	public CollectionLogPage(String name)
	{
		this.name = name;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public int getObtained()
	{
		return obtained;
	}

	public void setObtained(int obtained)
	{
		this.obtained = obtained;
	}

	public int getTotal()
	{
		return total;
	}

	public void setTotal(int total)
	{
		this.total = total;
	}

	public Map<String, Integer> getCounters()
	{
		return counters;
	}

	public void setCounters(Map<String, Integer> counters)
	{
		this.counters = counters == null ? new LinkedHashMap<>() : counters;
	}

	public Map<String, Integer> getItems()
	{
		return items;
	}

	public void setItems(Map<String, Integer> items)
	{
		this.items = items == null ? new LinkedHashMap<>() : items;
	}

	public long getUpdatedMillis()
	{
		return updatedMillis;
	}

	public void setUpdatedMillis(long updatedMillis)
	{
		this.updatedMillis = updatedMillis;
	}

	/**
	 * The counter the rating is based on. Pages can show several ("Kill count", "Chest opened",
	 * "Reward permit"); the largest is the one that actually generated the drop rolls.
	 */
	public int getPrimaryCount()
	{
		int best = 0;

		for (int value : counters.values())
		{
			best = Math.max(best, value);
		}

		return best;
	}

	public String getPrimaryCounterLabel()
	{
		String label = null;
		int best = -1;

		for (Map.Entry<String, Integer> entry : counters.entrySet())
		{
			if (entry.getValue() > best)
			{
				best = entry.getValue();
				label = entry.getKey();
			}
		}

		return label == null ? "Kill count" : label;
	}

	/**
	 * Value of a named counter, matched loosely so that "Corrupted Gauntlet completion count"
	 * survives punctuation and case differences. 0 when the page has no such counter.
	 */
	public int counterValue(String label)
	{
		String wanted = DropTable.normaliseCounter(label);

		for (Map.Entry<String, Integer> entry : counters.entrySet())
		{
			if (DropTable.normaliseCounter(entry.getKey()).equals(wanted))
			{
				return entry.getValue();
			}
		}

		return 0;
	}

	/** Total number of a given item obtained, matched on the normalised name. */
	public int quantityOf(String itemName)
	{
		String wanted = DropTable.normalise(itemName);

		for (Map.Entry<String, Integer> entry : items.entrySet())
		{
			if (DropTable.normalise(entry.getKey()).equals(wanted))
			{
				return entry.getValue();
			}
		}

		return 0;
	}

	/** Cheap fingerprint used to skip re-saving a page that has not changed since the last tick. */
	public String fingerprint()
	{
		return name + "|" + obtained + "/" + total + "|" + counters + "|" + items;
	}
}

package com.spoonmeter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class SpoonMeterPanel extends PluginPanel
{
	private final SpoonMeterPlugin plugin;

	private final JLabel verdictLabel = new JLabel();
	private final JLabel scoreLabel = new JLabel();
	private final JLabel blurbLabel = new JLabel();
	private final JLabel statsLabel = new JLabel();
	private final LuckBar overallBar = new LuckBar(10);
	private final JPanel sourceList = new JPanel(new DynamicGridLayout(0, 1, 0, 5));
	private final JComboBox<SortMode> sortBox = new JComboBox<>(SortMode.values());
	private final JLabel footerLabel = new JLabel();

	private SpoonReport report;
	private boolean updatingSortBox;

	public SpoonMeterPanel(SpoonMeterPlugin plugin)
	{
		this.plugin = plugin;

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 8));
		content.setOpaque(false);
		content.add(buildVerdictCard());
		content.add(buildControls());
		content.add(sourceList);
		content.add(buildFooter());

		sourceList.setOpaque(false);

		add(content, BorderLayout.NORTH);
		showEmpty();
	}

	private JPanel buildVerdictCard()
	{
		JPanel card = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(new EmptyBorder(10, 10, 10, 10));

		verdictLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		verdictLabel.setHorizontalAlignment(SwingConstants.CENTER);

		scoreLabel.setFont(FontManager.getRunescapeSmallFont());
		scoreLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		scoreLabel.setHorizontalAlignment(SwingConstants.CENTER);

		blurbLabel.setFont(FontManager.getRunescapeSmallFont());
		blurbLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		blurbLabel.setHorizontalAlignment(SwingConstants.CENTER);

		statsLabel.setFont(FontManager.getRunescapeSmallFont());
		statsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statsLabel.setHorizontalAlignment(SwingConstants.CENTER);

		card.add(verdictLabel);
		card.add(scoreLabel);
		card.add(overallBar);
		card.add(statsLabel);
		card.add(blurbLabel);
		return card;
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel(new BorderLayout(5, 0));
		controls.setOpaque(false);

		sortBox.setFocusable(false);
		sortBox.setFont(FontManager.getRunescapeSmallFont());
		sortBox.addActionListener(e ->
		{
			if (!updatingSortBox)
			{
				plugin.setSortMode((SortMode) sortBox.getSelectedItem());
			}
		});

		JButton copyButton = new JButton("Copy");
		copyButton.setFocusable(false);
		copyButton.setFont(FontManager.getRunescapeSmallFont());
		copyButton.setToolTipText("Copy the full breakdown to the clipboard");
		copyButton.addActionListener(e -> copyToClipboard());

		JButton chatButton = new JButton("Chat");
		chatButton.setFocusable(false);
		chatButton.setFont(FontManager.getRunescapeSmallFont());
		chatButton.setToolTipText("<html>Copy a one-line version, short enough for a game chat message."
			+ "<br>The game chatbox does not accept a paste, so this is for Discord and the like.</html>");
		chatButton.addActionListener(e -> copyChatLine());

		JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
		buttons.setOpaque(false);
		buttons.add(copyButton);
		buttons.add(chatButton);

		controls.add(sortBox, BorderLayout.CENTER);
		controls.add(buttons, BorderLayout.EAST);
		return controls;
	}

	private JPanel buildFooter()
	{
		JPanel footer = new JPanel(new BorderLayout());
		footer.setOpaque(false);

		footerLabel.setFont(FontManager.getRunescapeSmallFont());
		footerLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		footer.add(footerLabel, BorderLayout.CENTER);
		return footer;
	}

	/** Must be called on the EDT. */
	void update(SpoonReport report, SortMode sortMode)
	{
		this.report = report;

		updatingSortBox = true;
		sortBox.setSelectedItem(sortMode);
		updatingSortBox = false;

		sourceList.removeAll();

		if (report == null || report.isEmpty())
		{
			showEmpty();
			sourceList.revalidate();
			sourceList.repaint();
			return;
		}

		verdictLabel.setText(report.getRating().getTitle());
		verdictLabel.setForeground(report.getRating().getColor());
		scoreLabel.setText("Spoon score " + report.getSpoonScore() + " / 100");
		blurbLabel.setText("<html><div style='text-align:center'>" + report.getRating().getBlurb()
			+ "<br>Luckier than " + report.getSpoonScore() + "% of accounts at your KC.</div></html>");
		statsLabel.setText(SpoonSummary.WHOLE.format(report.getObtained()) + " uniques vs "
			+ SpoonSummary.ONE_DP.format(report.getExpected()) + " expected  ("
			+ SpoonSummary.ONE_DP.format(report.getRatio()) + "x)");
		overallBar.setPercentile(report.getPercentile());

		List<SpoonReport.SourceLine> sources = new ArrayList<>(report.getSources());
		sources.sort(sortMode.getComparator());

		for (SpoonReport.SourceLine source : sources)
		{
			sourceList.add(new SourceRow(source));
		}

		footerLabel.setText("<html>" + sources.size() + " rated of " + report.getPagesSeen()
			+ " pages read.<br>Open more collection log pages to feed the meter."
			+ "<br>* rates vary with team size or points.</html>");

		sourceList.revalidate();
		sourceList.repaint();
	}

	private void showEmpty()
	{
		verdictLabel.setText("No data yet");
		verdictLabel.setForeground(Color.WHITE);
		scoreLabel.setText("");
		statsLabel.setText("");
		overallBar.setPercentile(0.5);
		blurbLabel.setText("<html><div style='text-align:center'>Open your collection log and click "
			+ "through the boss pages you care about. Every page you view is read and remembered.</div></html>");
		footerLabel.setText(report == null ? "" : "<html>" + report.getPagesSeen()
			+ " pages read, none with enough KC to rate yet.</html>");
	}

	private void copyChatLine()
	{
		if (report == null || report.isEmpty())
		{
			return;
		}

		copy(SpoonSummary.chatLine(report, ""));
	}

	private void copyToClipboard()
	{
		if (report == null || report.isEmpty())
		{
			return;
		}

		copy(SpoonSummary.forClipboard(report, (SortMode) sortBox.getSelectedItem()));
	}

	private static void copy(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}
}

package com.spoonmeter;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The rating itself: every collection log page we have data and rates for, scored against how many
 * uniques the KC should have produced, plus the aggregate verdict for the account.
 */
public class SpoonReport
{
	/** One unique on a page: what it should have cost, and what it actually cost. */
	public static class ItemLine
	{
		private final String name;
		private final double chance;
		private final int obtained;
		private final double expected;
		private final double dryness;

		ItemLine(String name, double chance, int obtained, double expected, double dryness)
		{
			this.name = name;
			this.chance = chance;
			this.obtained = obtained;
			this.expected = expected;
			this.dryness = dryness;
		}

		public String getName()
		{
			return name;
		}

		/**
		 * Effective chance per attempt. On a page whose attempts are split across variants at
		 * different rates - normal and corrupted Gauntlet, say - this is the blend, so it moves as
		 * the split does.
		 */
		public double getChance()
		{
			return chance;
		}

		public int getObtained()
		{
			return obtained;
		}

		public double getExpected()
		{
			return expected;
		}

		/**
		 * Share of players who would already own this item after the same attempts. Only meaningful
		 * while you do not: 0.97 means 97 in 100 have it and you do not.
		 */
		public double getDryness()
		{
			return dryness;
		}
	}

	public static class SourceLine
	{
		private final String name;
		private final Map<String, Integer> counters;
		private final int kc;
		private final int obtained;
		private final double expected;
		private final double percentile;
		private final LuckRating rating;
		private final boolean approximate;
		private final List<ItemLine> items;

		SourceLine(String name, Map<String, Integer> counters, int kc, int obtained, double expected,
			double percentile, boolean approximate, List<ItemLine> items)
		{
			this.name = name;
			this.counters = counters;
			this.kc = kc;
			this.obtained = obtained;
			this.expected = expected;
			this.percentile = percentile;
			this.rating = LuckRating.fromPercentile(percentile);
			this.approximate = approximate;
			this.items = items;
		}

		public String getName()
		{
			return name;
		}

		/** The counters that actually fed the rating, in table order. */
		public Map<String, Integer> getCounters()
		{
			return counters;
		}

		/** Total attempts across every counted variant. */
		public int getKc()
		{
			return kc;
		}

		public int getObtained()
		{
			return obtained;
		}

		public double getExpected()
		{
			return expected;
		}

		public double getPercentile()
		{
			return percentile;
		}

		public LuckRating getRating()
		{
			return rating;
		}

		public boolean isApproximate()
		{
			return approximate;
		}

		public List<ItemLine> getItems()
		{
			return items;
		}

		/** Uniques per expected unique. 2.0 is double rate, 0.5 is half. */
		public double getRatio()
		{
			return expected <= 0 ? 1.0 : obtained / expected;
		}

		/** The item you are furthest behind on, or null if nothing notable is missing. */
		public ItemLine getDriestMissing()
		{
			ItemLine driest = null;

			for (ItemLine item : items)
			{
				if (item.getObtained() == 0 && (driest == null || item.getDryness() > driest.getDryness()))
				{
					driest = item;
				}
			}

			return driest != null && driest.getDryness() >= 0.5 ? driest : null;
		}
	}

	/** Running totals for one item while its variants are being added up. */
	private static final class Accumulator
	{
		private final String name;
		private double expected;
		private double missProbability = 1.0;

		private Accumulator(String name)
		{
			this.name = name;
		}
	}

	private final List<SourceLine> sources;
	private final int obtained;
	private final double expected;
	private final double percentile;
	private final LuckRating rating;
	private final int pagesSeen;

	private SpoonReport(List<SourceLine> sources, int obtained, double expected, double percentile, int pagesSeen)
	{
		this.sources = sources;
		this.obtained = obtained;
		this.expected = expected;
		this.percentile = percentile;
		this.rating = LuckRating.fromPercentile(percentile);
		this.pagesSeen = pagesSeen;
	}

	public List<SourceLine> getSources()
	{
		return Collections.unmodifiableList(sources);
	}

	public int getObtained()
	{
		return obtained;
	}

	public double getExpected()
	{
		return expected;
	}

	public double getPercentile()
	{
		return percentile;
	}

	public LuckRating getRating()
	{
		return rating;
	}

	public int getSpoonScore()
	{
		return LuckRating.spoonScore(percentile);
	}

	/** Pages we have data for, including ones with no drop rates or too little KC to rate. */
	public int getPagesSeen()
	{
		return pagesSeen;
	}

	public boolean isEmpty()
	{
		return sources.isEmpty();
	}

	public double getRatio()
	{
		return expected <= 0 ? 1.0 : obtained / expected;
	}

	/**
	 * Scores every page we can, then rolls them into one account-wide verdict.
	 *
	 * @param uniqueChances per-completion unique chance for the weight-based raid entries, keyed by
	 *                      the variant's uniqueChanceKey
	 * @param minKc         pages below this many attempts are ignored; a handful says nothing
	 */
	public static SpoonReport build(Collection<CollectionLogPage> pages, DropTable dropTable,
		Map<String, Double> uniqueChances, int minKc)
	{
		List<SourceLine> lines = new ArrayList<>();
		int totalObtained = 0;
		double totalExpected = 0;

		for (CollectionLogPage page : pages)
		{
			DropTable.Source source = dropTable.find(page.getName());

			if (source == null)
			{
				continue;
			}

			Map<String, Accumulator> accumulated = new LinkedHashMap<>();
			Map<String, Integer> countersUsed = new LinkedHashMap<>();
			int totalKc = 0;

			for (DropTable.Variant variant : source.getVariants())
			{
				String counter = variant.getCounter();
				int kc = counter == null ? page.getPrimaryCount() : page.counterValue(counter);

				if (kc <= 0)
				{
					continue;
				}

				double uniqueChance = 0.0;

				if (variant.getUniqueChanceKey() != null)
				{
					Double configured = uniqueChances.get(variant.getUniqueChanceKey());

					if (configured == null || configured <= 0)
					{
						continue;
					}

					uniqueChance = configured;
				}

				totalKc += kc;
				countersUsed.put(counter == null ? page.getPrimaryCounterLabel() : counter, kc);

				for (DropTable.Item item : variant.getItems())
				{
					double chance = DropTable.probability(variant, item, uniqueChance);

					if (chance <= 0)
					{
						continue;
					}

					Accumulator accumulator = accumulated.computeIfAbsent(
						DropTable.normalise(item.getName()), key -> new Accumulator(item.getName()));

					accumulator.expected += kc * chance;
					accumulator.missProbability *= Math.pow(1.0 - chance, kc);
				}
			}

			if (totalKc < Math.max(1, minKc) || accumulated.isEmpty())
			{
				continue;
			}

			List<ItemLine> items = new ArrayList<>();
			int pageObtained = 0;
			double pageExpected = 0;

			for (Accumulator accumulator : accumulated.values())
			{
				int count = page.quantityOf(accumulator.name);

				pageObtained += count;
				pageExpected += accumulator.expected;

				items.add(new ItemLine(accumulator.name, accumulator.expected / totalKc, count,
					accumulator.expected, 1.0 - accumulator.missProbability));
			}

			if (pageExpected <= 0)
			{
				continue;
			}

			totalObtained += pageObtained;
			totalExpected += pageExpected;

			lines.add(new SourceLine(page.getName(), countersUsed, totalKc, pageObtained, pageExpected,
				LuckCalculator.luckPercentile(pageExpected, pageObtained), source.isApprox(), items));
		}

		double percentile = LuckCalculator.luckPercentile(totalExpected, totalObtained);
		return new SpoonReport(lines, totalObtained, totalExpected, percentile, pages.size());
	}
}

package com.spoonmeter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
